# At a science fair, 70 students sign up, and then 26 more students sign up. Another 70 students join, and the organizers split all the students equally between 2 groups. Each student in one group receives 79 stickers. How many stickers does that group receive?
program GSM9112 implements ISolver {
    type Input = str;
    type Output = quantity;
    @external
    public function parse(raw: str): Input { return raw; }

    public pure function verify(input: Input, output: Output): bool { return true; }



    @external
    public function solve(input: Input): Output {
        create s0 : quantity;   # step 0: 70 + 26 = 96
        assign s0 = 70;
        add s0, 26;
        create s1 : quantity;   # step 1: 96 + 70 = 166
        assign s1 = 0;
        add s1, s0;
        add s1, 70;
        create s2 : quantity;   # step 2: 166 / 2 = 83
        assign s2 = 0;
        add s2, s1;
        div s2, 2;
        create s3 : quantity;   # step 3: 83 * 79 = 6557
        assign s3 = 0;
        add s3, s2;
        mul s3, 79;
        sum s3;
        query s3;
        return s3;
    }
}

# During a summer job, a worker divides 175 flyers equally among 7 teams, then adds 105 flyers to each team’s pile. She makes 7 batches of that many flyers, adds 110 more flyers, and divides them equally among 4 delivery routes. How many flyers go on each route?
program GSM2394 implements ISolver {
    type Input = str;
    type Output = quantity;
    @external
    public function parse(raw: str): Input { return raw; }

    public pure function verify(input: Input, output: Output): bool { return true; }



    @external
    public function solve(input: Input): Output {
        create s0 : quantity;   # step 0: 175 / 7 = 25
        assign s0 = 175;
        div s0, 7;
        create s1 : quantity;   # step 1: 25 + 105 = 130
        assign s1 = 0;
        add s1, s0;
        add s1, 105;
        create s2 : quantity;   # step 2: 130 * 7 = 910
        assign s2 = 0;
        add s2, s1;
        mul s2, 7;
        create s3 : quantity;   # step 3: 910 + 110 = 1020
        assign s3 = 0;
        add s3, s2;
        add s3, 110;
        create s4 : quantity;   # step 4: 1020 / 4 = 255
        assign s4 = 0;
        add s4, s3;
        div s4, 4;
        sum s4;
        query s4;
        return s4;
    }
}

